head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "uldmgt50300";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.list();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50300.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_listForm = { action: "", method: 'post', target: '' };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'uldmgt50300.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name form_1_onsubmit
 * @description form_1 onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.form_1_onsubmit = function(e){
    try {
        return false

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50300.form_1_onsubmit' }); }
};

/**
 * @method
 * @name img_15_onclick
 * @description img_15 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_15_onclick = async function(e){
    try {
        await scwin.addLaw()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50300.img_15_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_List_xhr
 * @description List xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_List_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_List_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_List_xhr", unresolved: "action:self_submit:tx_fn_List_xhr" };
};

/**
 * @method
 * @name tx_fn_DelDisclosureLaw_xhr
 * @description Del Disclosure Law xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_DelDisclosureLaw_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_DelDisclosureLaw_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_DelDisclosureLaw_xhr", unresolved: "action:self_submit:tx_fn_DelDisclosureLaw_xhr" };
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name list
 * @description list 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.list = async function () {
    scwin.form_listForm.action = "/filing/disclosureLaw.do";
    $c.util.getComponent('dma_ListXhrReq').set('method', "findDisclosureLaws");
    $c.util.getComponent('txt_lawListDiv').setValue(await scwin.tx_fn_List_xhr());
};

/**
 * @method
 * @name onEnter
 * @description on Enter 처리
 * @returns {void}
 * @hidden N
 */
scwin.onEnter = function () {
    /* empty */
};

/**
 * @method
 * @name findLawItems
 * @description find Law Items 처리
 * @param {*} lawNo lawNo
 * @returns {void}
 * @hidden N
 */
scwin.findLawItems = function (lawNo) {
    $c.win.moveUrl("/filing/onlineDisclosureLaw.do?method=findDisclosureLawItemDisplay&lawNo=" + lawNo);
};

/**
 * @method
 * @name addLawItems
 * @description add Law Items 처리
 * @param {*} lawNo lawNo
 * @returns {void}
 * @hidden N
 */
scwin.addLawItems = function (lawNo) {
    $c.win.moveUrl("/filing/updateOnlineDisclosureLaw.do?method=prepareUpdateDisclosureLawItems&lawNo=" + lawNo);
};

/**
 * @method
 * @name addLaw
 * @description add Law 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.addLaw = async function () {
    const _url = "/filing/updateDisclosureLaw.do?method=prepareUpdateDisclosureLaw&mode=create";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    await $c.win.openPopup((function (__u) { let __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), { id: "lawPop", popupName: "lawPop" }, {});
};

/**
 * @method
 * @name modDisclosureLaw
 * @description mod Disclosure Law 처리
 * @param {*} lawNo lawNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.modDisclosureLaw = async function (lawNo) {
    const _url = "/filing/updateDisclosureLaw.do?method=prepareUpdateDisclosureLaw&lawNo=" + lawNo + "&mode=update";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    await $c.win.openPopup((function (__u) { let __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), { id: "lawPop", popupName: "lawPop", width: "600", height: "280" }, {});
};

/**
 * @method
 * @name delDisclosureLaw
 * @description del Disclosure Law 처리
 * @param {*} lawNo lawNo
 * @param {*} lawTitle lawTitle
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delDisclosureLaw = async function (lawNo, lawTitle) {
    const _confirm = await $c.win.confirm("공시법규 '" + lawTitle + "'를\n삭제하시겠습니까?");
    if (!_confirm) {
        return;
    }
    $c.util.getComponent('dma_ListXhrReq').set('lawNo', lawNo);
    scwin.form_listForm.action = "/filing/disclosureLaw.do";
    $c.util.getComponent('dma_ListXhrReq').set('method', "deleteDisclosureLaw");
    $c.util.getComponent('txt_lawListDiv').setValue(await scwin.tx_fn_DelDisclosureLaw_xhr());
};

/**
 * @method
 * @name downloadLawBinfile
 * @description download Law Binfile 처리
 * @param {*} lawNo lawNo
 * @returns {void}
 * @hidden N
 */
scwin.downloadLawBinfile = function (lawNo) {
    $c.win.moveUrl("/filing/disclosureLaw.do?method=downloadLawBinfile&lawNo=" + lawNo);
};
